import asyncio
import httpx
import time
import statistics
import uuid
import subprocess

# 1. Dynamically find the active AWS Load Balancer URL
try:
    cmd_url = "kubectl get svc nexora-gateway-istio -n nexora -o jsonpath='{.status.loadBalancer.ingress[0].hostname}'"
    elb_host = subprocess.check_output(cmd_url, shell=True, text=True).strip().replace("'", "")
    BASE_URL = f"http://{elb_host}/api" if elb_host else "http://localhost:8000/api"
except Exception:
    BASE_URL = "http://localhost:8000/api"

# 2. Dynamically fetch the REAL random secret generated by AWS Secrets Manager!
try:
    cmd_secret = "kubectl get secret db-secret -n nexora -o jsonpath='{.data.INTERNAL_SERVICE_SECRET}' | base64 -d"
    TEST_KEY = subprocess.check_output(cmd_secret, shell=True, text=True).strip()
except Exception:
    TEST_KEY = "nexora-internal-secret-key-123"

PAIRS_COUNT = 4          # 4 independent account pairs
TRANSFERS_PER_PAIR = 25  # 25 transfers each = 100 total requests

latencies = []

async def execute_transfer(client, token, receiver_name):
    start = time.perf_counter()
    key = str(uuid.uuid4())
    try:
        res = await client.post(
            f"{BASE_URL}/transfer",
            headers={
                "Authorization": f"Bearer {token}",
                "Idempotency-Key": key,
                "X-Internal-Service-Key": TEST_KEY
            },
            json={"receiver_username": receiver_name, "amount": "1.00"}
        )
        duration = (time.perf_counter() - start) * 1000 # ms
        latencies.append((duration, res.status_code))
    except Exception:
        latencies.append((9999, 500))

async def main():
    print(f"🎯 Target URL: {BASE_URL}")
    print(f"🔑 Using Live AWS Secret: {TEST_KEY[:4]}...{TEST_KEY[-4:]}")
    print(f"🚀 Benchmarking Distributed Workload: 100 transfers across {PAIRS_COUNT} independent account pairs...")
    
    async with httpx.AsyncClient(timeout=15.0) as client:
        # Provision independent pairs sequentially
        pairs = []
        for i in range(PAIRS_COUNT):
            uid = uuid.uuid4().hex[:4]
            sender = f"user_s_{i}_{uid}"
            receiver = f"user_r_{i}_{uid}"
            
            # 1. Signup Sender
            res_s = await client.post(f"{BASE_URL}/signup", headers={"X-Internal-Service-Key": TEST_KEY}, json={"username": sender, "email": f"{sender}@test.com", "phone": "555-0101", "password": "Password123!"})
            assert res_s.status_code == 201, f"Signup failed for {sender}: {res_s.text}"
            
            # 2. Signup Receiver
            res_r = await client.post(f"{BASE_URL}/signup", headers={"X-Internal-Service-Key": TEST_KEY}, json={"username": receiver, "email": f"{receiver}@test.com", "phone": "555-0102", "password": "Password123!"})
            assert res_r.status_code == 201, f"Signup failed for {receiver}: {res_r.text}"
            
            # 3. Login Sender
            login_res = await client.post(f"{BASE_URL}/login", headers={"X-Internal-Service-Key": TEST_KEY}, json={"username": sender, "password": "Password123!"})
            assert login_res.status_code == 200, f"Login failed for {sender}: {login_res.text}"
            
            token = login_res.json()["access_token"]
            pairs.append((token, receiver))
            print(f"  ✅ Provisioned pair {i+1}/{PAIRS_COUNT}: {sender} -> {receiver}")

        print("\n⚡ Firing 100 concurrent transfers across all pairs...")
        tasks = []
        start_total = time.perf_counter()
        for token, receiver in pairs:
            for _ in range(TRANSFERS_PER_PAIR):
                tasks.append(execute_transfer(client, token, receiver))

        await asyncio.gather(*tasks)
        total_time = time.perf_counter() - start_total

    # Calculate Percentiles
    times = [l[0] for l in latencies if l[0] < 9000]
    success_count = sum(1 for l in latencies if l[1] == 200)

    print("\n=======================================================")
    print("      DISTRIBUTED WORKLOAD BENCHMARK RESULTS           ")
    print("=======================================================")
    print(f"Total Requests:       {len(latencies)}")
    print(f"Independent Pairs:    {PAIRS_COUNT}")
    print(f"Successful Transfers: {success_count}/{len(latencies)} ({success_count/len(latencies)*100:.1f}%)")
    print(f"Total Duration:       {total_time:.2f} seconds")
    print(f"Throughput:           {len(latencies) / total_time:.2f} req/sec")
    print("-------------------------------------------------------")
    if times:
        print(f"p50 Latency (Median): {statistics.median(times):.2f} ms")
        print(f"p95 Latency:          {statistics.quantiles(times, n=20)[18]:.2f} ms")
        print(f"p99 Latency:          {statistics.quantiles(times, n=100)[98]:.2f} ms")
    print("=======================================================")

if __name__ == "__main__":
    asyncio.run(main())